Challenge: jump_to_latest.Trees.cs:
using System.Windows;
using System.Windows.Media;

namespace LessonApp;

public static class Trees
{
    public static T? FindDescendant<T>(DependencyObject parent) where T : DependencyObject
    {
        for (int index = 0; index < VisualTreeHelper.GetChildrenCount(parent); index++)
        {
            DependencyObject child = VisualTreeHelper.GetChild(parent, index);
            if (child is T match) return match;
            T? deeper = FindDescendant<T>(child);
            if (deeper != null) return deeper;
        }
        return null;
    }

    public static T? FindAncestor<T>(DependencyObject child) where T : DependencyObject
    {
        DependencyObject? current = VisualTreeHelper.GetParent(child);
        while (current != null)
        {
            if (current is T match) return match;
            current = VisualTreeHelper.GetParent(current);
        }
        return null;
    }
}

