Challenge: upper_case.Behaviors.cs:
using System.Windows;
using System.Windows.Controls;

namespace LessonApp;

public static class Behaviors
{
    public static readonly DependencyProperty ForceUpperCaseProperty = DependencyProperty.RegisterAttached(
        "ForceUpperCase", typeof(bool), typeof(Behaviors), new PropertyMetadata(false, OnForceUpperCaseChanged));

    public static bool GetForceUpperCase(TextBox box) => (bool)box.GetValue(ForceUpperCaseProperty);
    public static void SetForceUpperCase(TextBox box, bool value) => box.SetValue(ForceUpperCaseProperty, value);

    private static void OnForceUpperCaseChanged(DependencyObject element, DependencyPropertyChangedEventArgs change)
    {
        var box = (TextBox)element;
        if ((bool)change.NewValue)
        {
            box.TextChanged += OnTextChanged;
            MakeUpper(box);
        }
        else
        {
            box.TextChanged -= OnTextChanged;
        }
    }

    private static void OnTextChanged(object sender, TextChangedEventArgs e) => MakeUpper((TextBox)sender);

    private static void MakeUpper(TextBox box)
    {
        string upper = box.Text.ToUpperInvariant();
        if (upper != box.Text) box.Text = upper;
    }
}

