using Microsoft.Data.Sqlite;

namespace LessonApp;

public class SqliteProductRepository : IProductRepository
{
    private readonly SqliteConnection connection;

    public SqliteProductRepository(SqliteConnection connection) => this.connection = connection;

    public async Task CreateSchemaAsync()
    {
        var command = connection.CreateCommand();
        command.CommandText = "CREATE TABLE IF NOT EXISTS Products (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE, Price REAL NOT NULL)";
        await command.ExecuteNonQueryAsync();
    }

    public async Task<long> AddAsync(Product product)
    {
        var command = connection.CreateCommand();
        command.CommandText = "INSERT INTO Products (Name, Price) VALUES ($name, $price) RETURNING Id";
        command.Parameters.AddWithValue("$name", product.Name);
        command.Parameters.AddWithValue("$price", product.Price);
        return Convert.ToInt64(await command.ExecuteScalarAsync());
    }

    public async Task<IReadOnlyList<Product>> GetAllAsync()
    {
        var command = connection.CreateCommand();
        command.CommandText = "SELECT Id, Name, Price FROM Products ORDER BY Name";
        return await ReadProducts(command);
    }

    public async Task<Product?> FindByNameAsync(string name)
    {
        var command = connection.CreateCommand();
        command.CommandText = "SELECT Id, Name, Price FROM Products WHERE Name = $name";
        command.Parameters.AddWithValue("$name", name);
        return (await ReadProducts(command)).FirstOrDefault();
    }

    private static async Task<List<Product>> ReadProducts(SqliteCommand command)
    {
        var products = new List<Product>();
        using var reader = await command.ExecuteReaderAsync();
        while (await reader.ReadAsync())
            products.Add(new Product(reader.GetInt64(0), reader.GetString(1), reader.GetDouble(2)));
        return products;
    }
}

Challenge: atomic_import.ProductImporter.cs:
using Microsoft.Data.Sqlite;

namespace LessonApp;

public class ProductImporter
{
    private readonly SqliteConnection connection;

    public ProductImporter(SqliteConnection connection) => this.connection = connection;

    public async Task<int> ImportAsync(IEnumerable<Product> products)
    {
        using var transaction = connection.BeginTransaction();
        int imported = 0;
        try
        {
            foreach (var product in products)
            {
                var command = connection.CreateCommand();
                command.Transaction = transaction;
                command.CommandText = "INSERT INTO Products (Name, Price) VALUES ($name, $price)";
                command.Parameters.AddWithValue("$name", product.Name);
                command.Parameters.AddWithValue("$price", product.Price);
                await command.ExecuteNonQueryAsync();
                imported++;
            }
            transaction.Commit();
            return imported;
        }
        catch (SqliteException)
        {
            transaction.Rollback();
            throw;
        }
    }
}

